using System;
using System.IO;
using System.Linq;
using UnityEngine;
using MaritimeLegend.Domain;
using GUI=MaritimeLegend.LiveGui;
using GUIUtility=MaritimeLegend.LiveGuiUtility;
namespace MaritimeLegend {
public partial class MaritimeGame {
internal void StartBattle(bool final){finalBattle=final;page="战斗";battleEnemy=final?130:70;enemySails=100;battleCooldown=0;battleEnemyCooldown=3;battlePlayer=new Vector2(640,650);battleTarget=new Vector2(1080,420);battleAngle=-.35f;battleEnemyAngle=2.8f;}
internal void BattleTick(float dt){dt*=s.settings.battleSpeed;battleAngle+=(Input.GetKey(KeyCode.D)?1:Input.GetKey(KeyCode.A)?-1:0)*dt*1.4f;battlePlayer+=new Vector2(Mathf.Cos(battleAngle),Mathf.Sin(battleAngle))*dt*55*(Input.GetKey(KeyCode.S)?.3f:1);battlePlayer.x=Mathf.Clamp(battlePlayer.x,100,1760);battlePlayer.y=Mathf.Clamp(battlePlayer.y,250,790);Vector2 toward=battlePlayer-battleTarget;float want=Mathf.Atan2(toward.y,toward.x)+(toward.magnitude<360?Mathf.PI/2:0);battleEnemyAngle=Mathf.LerpAngle(battleEnemyAngle*Mathf.Rad2Deg,want*Mathf.Rad2Deg,dt*.7f)*Mathf.Deg2Rad;battleTarget+=new Vector2(Mathf.Cos(battleEnemyAngle),Mathf.Sin(battleEnemyAngle))*dt*(enemySails>20?42:17);battleTarget.x=Mathf.Clamp(battleTarget.x,100,1760);battleTarget.y=Mathf.Clamp(battleTarget.y,250,790);battleCooldown-=dt;battleEnemyCooldown-=dt;if(Input.GetKeyDown(KeyCode.Space))Fire();if(battleEnemyCooldown<=0&&toward.magnitude<490&&Broadside(battleTarget,battlePlayer,battleEnemyAngle)){s.ships[0].hull-=g.HasPartner(5)?4:5;battleEnemyCooldown=3.5f;sound.Cue(2);}if(s.ships[0].hull<=0){Notify(g.Rescue(),10);page="城市";}if(battleEnemy<=0){g.RewardBattleVictory(finalBattle);if(finalBattle){page="结局";Save(false);}else page="城市";sound.Cue(9);}}
internal bool Broadside(Vector2 from,Vector2 to,float angle){var dir=(to-from).normalized;return Mathf.Abs(Vector2.Dot(dir,new Vector2(Mathf.Cos(angle),Mathf.Sin(angle))))<.72f;}
internal void Fire(){var sh=s.ships[0];if(battleCooldown>0){Notify("火炮正在装填");return;}if(sh.ammo<=0){Notify("弹药耗尽，请撤离整备");return;}if(Vector2.Distance(battlePlayer,battleTarget)>520||!Broadside(battlePlayer,battleTarget,battleAngle)){Notify("敌舰不在侧舷射界；转舵使船侧朝向敌人（距离520以内）");return;}sh.ammo--;shotEffect=.3f;battleCooldown=g.HasPartner(11)?1.84f:2;float damage=15+c.ships[sh.type].guns*3+sh.level*2+s.skillLevels[9];if(targetSails)enemySails=Mathf.Max(0,enemySails-damage);else battleEnemy-=damage;sound.Cue(2);}
internal void BattleUI(){Panel(new Rect(30,130,1860,755));Fill(new Rect(40,220,1840,650),new Color(.04f,.19f,.25f));for(int i=0;i<18;i++)Line(new Vector2(45,245+i*34),new Vector2(1860,245+i*34),new Color(.1f,.26f,.29f),1);if(shotEffect>0&&s.settings.animations)Line(battlePlayer,battleTarget,new Color(1,.85f,.3f),4);DrawShip(battlePlayer,battleAngle*Mathf.Rad2Deg,gold);DrawShip(battleTarget,battleEnemyAngle*Mathf.Rad2Deg,new Color(.8f,.2f,.18f));Label(65,148,1100,65,(finalBattle?"最终挑战 · 黑旗旗舰":"海战演练")+"  敌舰 "+battleEnemy.ToString("0")+" / 帆 "+enemySails.ToString("0"),heading);Label(70,770,1100,80,"A/D 转舵 · S 减速 · 空格炮击 · 必须让侧舷对准目标\n船体 "+s.ships[0].hull.ToString("0")+"  弹药 "+s.ships[0].ammo+"  装填 "+Math.Max(0,battleCooldown).ToString("0.0"),small);if(Btn(1430,250,370,60,"炮击 · 空格"))Fire();if(Btn(1430,325,370,60,targetSails?"目标：风帆":"目标：船体"))targetSails=!targetSails;if(Btn(1430,720,370,60,"撤离救援")){Notify(g.Rescue());page="城市";}}
}}
